/**
 * A single naming-convention violation discovered while linting a Concerto
 * model AST.
 */
export interface LintViolation {
    /** Machine readable identifier for the rule that was broken. */
    code: string;
    /** Human readable description of the violation. */
    message: string;
    /** The offending name (type declaration, property or enum constant). */
    name: string;
    /** Path to the offending node within the AST. */
    path: Array<string | number>;
    /** Severity of the violation. */
    severity: string;
}

/**
 * The set of metamodel declaration classes that are considered "type
 * declarations" and must therefore follow the camelCase convention. Scalar
 * declarations are handled separately as they are represented using a typed
 * class name (e.g. `StringScalar`).
 */
const TYPE_DECLARATION_CLASSES = new Set([
    'ConceptDeclaration',
    'AssetDeclaration',
    'ParticipantDeclaration',
    'TransactionDeclaration',
    'EventDeclaration',
    'EnumDeclaration',
    'ScalarDeclaration',
]);

/**
 * Returns the short (unqualified) class name for a metamodel `$class` value.
 * For example `concerto.metamodel@1.0.0.ConceptDeclaration` becomes
 * `ConceptDeclaration`.
 *
 * @param $class the fully qualified metamodel class name
 * @returns the short class name, or an empty string when unavailable
 */
function shortClassName($class: unknown): string {
    if (typeof $class !== 'string') {
        return '';
    }
    const parts = $class.split('.');
    return parts[parts.length - 1] ?? '';
}

/**
 * Determines whether a declaration node represents a Concerto type declaration
 * (concept, asset, participant, transaction, event, enum or scalar).
 *
 * @param shortName the short metamodel class name of the declaration
 * @returns true if the declaration is a type declaration
 */
function isTypeDeclaration(shortName: string): boolean {
    return TYPE_DECLARATION_CLASSES.has(shortName) || shortName.endsWith('Scalar');
}

/**
 * Returns true when a name begins with an uppercase letter.
 *
 * @param name the name to test
 */
function startsWithUpperCase(name: string): boolean {
    return name.length > 0 && name[0] === name[0].toUpperCase() && name[0] !== name[0].toLowerCase();
}

/**
 * Returns true when a name is formatted using UPPER_SNAKE_CASE, i.e. it only
 * contains uppercase letters, digits and underscores and begins with an
 * uppercase letter.
 *
 * @param name the name to test
 */
function isUpperSnakeCase(name: string): boolean {
    return /^[A-Z][A-Z0-9_]*$/.test(name);
}

/**
 * Collects every declaration node from a parsed AST. The AST may either be a
 * single model (with a `declarations` array) or a container of models (with a
 * `models` array, each of which has its own `declarations`).
 *
 * @param root the parsed AST object
 * @returns an array of declaration nodes
 */
function collectDeclarations(root: any): any[] {
    const declarations: any[] = [];
    if (!root || typeof root !== 'object') {
        return declarations;
    }
    if (Array.isArray(root.models)) {
        for (const model of root.models) {
            if (model && Array.isArray(model.declarations)) {
                declarations.push(...model.declarations);
            }
        }
    }
    if (Array.isArray(root.declarations)) {
        declarations.push(...root.declarations);
    }
    return declarations;
}

/**
 * Lints a Concerto model AST, enforcing the following naming conventions:
 *
 * - Type declarations (concept, asset, participant, transaction, event, enum,
 *   scalar) must be camelCase (must not begin with an uppercase letter).
 * - Properties (fields) in non-enum types must be PascalCase (must begin with
 *   an uppercase letter).
 * - Enum constants must be UPPER_SNAKE_CASE.
 *
 * @param ast a JSON-serialized Concerto model AST string
 * @returns a promise resolving to an array of violation objects. The array is
 *   empty when no naming violations are detected.
 */
export async function lintAST(ast: string): Promise<Array<any>> {
    let root: any;
    if (typeof ast === 'string') {
        root = JSON.parse(ast);
    } else {
        // Be lenient and accept an already-parsed AST object.
        root = ast;
    }

    const violations: LintViolation[] = [];
    const declarations = collectDeclarations(root);

    declarations.forEach((declaration, declarationIndex) => {
        if (!declaration || typeof declaration !== 'object') {
            return;
        }

        const shortName = shortClassName(declaration.$class);
        const declarationName: unknown = declaration.name;

        // Rule: type declarations must be camelCase.
        if (isTypeDeclaration(shortName) && typeof declarationName === 'string') {
            if (startsWithUpperCase(declarationName)) {
                violations.push({
                    code: 'type-declaration-camel-case',
                    message: `Type declaration "${declarationName}" should use camelCase.`,
                    name: declarationName,
                    path: ['declarations', declarationIndex, 'name'],
                    severity: 'warning',
                });
            }
        }

        const isEnum = shortName === 'EnumDeclaration';
        const properties = Array.isArray(declaration.properties) ? declaration.properties : [];

        properties.forEach((property: any, propertyIndex: number) => {
            if (!property || typeof property !== 'object' || typeof property.name !== 'string') {
                return;
            }
            const propertyName: string = property.name;

            if (isEnum) {
                // Rule: enum constants must be UPPER_SNAKE_CASE.
                if (!isUpperSnakeCase(propertyName)) {
                    violations.push({
                        code: 'enum-constant-upper-snake-case',
                        message: `Enum constant "${propertyName}" should use UPPER_SNAKE_CASE.`,
                        name: propertyName,
                        path: ['declarations', declarationIndex, 'properties', propertyIndex, 'name'],
                        severity: 'warning',
                    });
                }
            } else {
                // Rule: properties in non-enum types must be PascalCase.
                if (!startsWithUpperCase(propertyName)) {
                    violations.push({
                        code: 'property-pascal-case',
                        message: `Property "${propertyName}" should use PascalCase.`,
                        name: propertyName,
                        path: ['declarations', declarationIndex, 'properties', propertyIndex, 'name'],
                        severity: 'warning',
                    });
                }
            }
        });
    });

    return violations;
}

export default lintAST;
